n.exploreUrl:
@js:
var result = [];
var push = function(title, url, size) {
result.push({"title": title, "url": url, "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": size}});
};
var tagUrl = "https://m.vipxiaoshuo.org/sort/";
var tag = java.ajax(tagUrl);
var tagList = org.jsoup.Jsoup.parse(tag).select(".sortChannel_nav a");
var tagSize = 0.4;
push("分类", null, 1);
for (var i = 0; i < tagList.length; i++) {
var title = org.jsoup.Jsoup.parse(tagList[i]).text();
var url = String(tagList[i].attr("href"))+"{{page}}.html"
title = String(title).replace(/\s/g, "");
push(title, url, tagSize);
}
JSON.stringify(result);
